void func_80196854_6C1524(u16 actor_index) {
    Actor* actor;
    s16 difference_x;
    s16 position_y;
    s16 position_x;

    if (!(gActors[MARINA_AIM_INDEX].flags & ACTOR_FLAG_ACTIVE)) {
        gActors[actor_index].flags = ACTOR_FLAG_NONE;
        return;
    }

    if ((gActors[actor_index].state == 0) && !(gActors[ROCKET_FIST_INDEX].flags & ACTOR_FLAG_DRAW)) {
        gActors[actor_index].state++;
    }

    if (gActors[actor_index].state) {
        gActors[actor_index].colorA = Math_ApproachS32(gActors[actor_index].colorA, 0, 0x10);
        if (gActors[actor_index].colorA == 0) {
            gActors[actor_index].flags = ACTOR_FLAG_NONE;
            return;
        }
        gActors[actor_index].scaleX -= 0.05;
    }
    else {
        gActors[actor_index].colorA = Math_ApproachS32(gActors[actor_index].colorA, 0xFF, 2);
        gActors[actor_index].scaleX = Math_ApproachF32(gActors[actor_index].scaleX, 0.9f, 0.005f);
    }
    gActors[actor_index].scaleY = gActors[actor_index].scaleX;
    position_x = gActors[actor_index].posX.whole;
    gActors[actor_index].posZ.whole = gActors[MAIN_BOSS_INDEX].posZ.whole + 0x20;
    difference_x = position_x - gActors[MAIN_BOSS_INDEX].posX.whole;
    if (difference_x < 0) {
        if (difference_x < -104) {
            gActors[actor_index].posX.whole = (position_x - difference_x) - 104;
        }
    }
    else if (difference_x >= 105) {
        gActors[actor_index].posX.whole = (position_x - difference_x) + 104;
    }
    position_y = gActors[actor_index].posY.whole;
    if (position_y >= 113) {
        gActors[actor_index].posY.whole = 112;
    }
    else if (position_y < 0x10) {
        gActors[actor_index].posY.whole = 0x10;
    }

    if (gActors[actor_index].colorA != 0xFF) {
        return;
    }

    if (gButtonHold & gButton_DUp) {
        if (gButtonHold & gButton_DLeft) {
            func_801965D0_6C12A0(actor_index, COS_DEG_90 + COS_DEG_45);
            func_801966B0_6C1380(actor_index, COS_DEG_90 + COS_DEG_45);
        }
        else if (gButtonHold & gButton_DRight) {
            func_801965D0_6C12A0(actor_index, COS_DEG_45);
            func_801966B0_6C1380(actor_index, COS_DEG_45);
        }
        else {
            func_80196794_6C1464(actor_index);
            func_801966B0_6C1380(actor_index, COS_DEG_90);
        }
    }
    else if (gButtonHold & gButton_DDown) {
        if (gButtonHold & gButton_DLeft) {
            func_801965D0_6C12A0(actor_index, COS_DEG_180 + COS_DEG_45);
            func_801966B0_6C1380(actor_index, COS_DEG_180 + COS_DEG_45);
        }
        else if (gButtonHold & gButton_DRight) {
            func_801965D0_6C12A0(actor_index, COS_DEG_360 - COS_DEG_45);
            func_801966B0_6C1380(actor_index, COS_DEG_360 - COS_DEG_45);
        }
        else {
            func_80196794_6C1464(actor_index);
            func_801966B0_6C1380(actor_index, COS_DEG_180 + COS_DEG_90);
        }
    }
    else {
        if (gButtonHold & gButton_DRight) {
            func_801965D0_6C12A0(actor_index, 0);
        }
        else if (gButtonHold & gButton_DLeft) {
            func_801965D0_6C12A0(actor_index, COS_DEG_180);
        }
        else {
            func_80196794_6C1464(actor_index);
        }
        func_801967F4_6C14C4(actor_index);
    }
    actor = &gActors[actor_index];
    gPlayerActor.posX.whole = actor->posX.whole;
    gPlayerPosX.whole = gScreenPosCurrentX.whole + actor->posX.whole;
    gPlayerActor.posY.whole = actor->posY.whole;
    gPlayerPosY.whole = gScreenPosCurrentY.whole + actor->posY.whole;
}

